{"implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    diagnostics = []
    accepted = []
    for call in calls:
        gain = call['loss_without_call'] - call['loss_with_call']
        normalized_gain = gain / call['prediction_tokens']
        accepted_flag = call['parseable'] and normalized_gain >= threshold
        diagnostics.append({
            'accepted': accepted_flag,
            'call_id': call['call_id'],
            'normalized_gain': normalized_gain
        })
        if accepted_flag:
            accepted.append(call['call_id'])
    return {
        'accepted_call_ids': accepted,
        'diagnostics': diagnostics
    }"}
